import { API_BASE_URL } from '../config/api';

export interface Message {
  id: string;
  threadId: string;
  senderId: string;
  text: string;
  sentAt: string;
  pending?: boolean;
}

export async function fetchMessages(threadId: string): Promise<Message[]> {
  const response = await fetch(`${API_BASE_URL}/threads/${threadId}/messages`);
  if (!response.ok) throw new Error(`Messages failed with status ${response.status}`);
  return (await response.json()) as Message[];
}

export async function sendMessage(threadId: string, text: string, clientId: string): Promise<Message> {
  const response = await fetch(`${API_BASE_URL}/threads/${threadId}/messages`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ text, clientId }),
  });
  if (!response.ok) throw new Error(`Send failed with status ${response.status}`);
  return (await response.json()) as Message;
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, FlatList, StyleSheet, SafeAreaView, KeyboardAvoidingView, Platform, ActivityIndicator } from 'react-native';
import { fetchMessages, sendMessage, type Message } from '../services/messages';

const colors = {
  accent: '#f05039',
  muted: '#8a8f8a',
  bg: '#0f120e',
  border: '#242a24',
  text: '#f5f5f0',
  surface: '#1a1f1a',
  danger: '#ff6b5e',
}

const THREAD_ID = 'thread-1';
const MY_ID = 'me';

export function ChatScreen(): JSX.Element {
  const [messages, setMessages] = useState<Message[]>([]);
  const [draft, setDraft] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const listRef = useRef<FlatList<Message>>(null);
  const counter = useRef(0);

    const load = useCallback(async () => {

    try {
      const data = await fetchMessages(THREAD_ID);
      setMessages(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load messages.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const sorted = useMemo(() => [...messages].sort((a, b) => a.sentAt.localeCompare(b.sentAt)), [messages]);

  const send = useCallback(async () => {
    const text = draft.trim();
    if (!text) return;
    const clientId = `local-${++counter.current}`;
    const optimistic: Message = { id: clientId, threadId: THREAD_ID, senderId: MY_ID, text, sentAt: new Date().toISOString(), pending: true };
    setMessages(prev => [...prev, optimistic]);
    setDraft('');
    try {
      const confirmed = await sendMessage(THREAD_ID, text, clientId);
      setMessages(prev => prev.map(m => (m.id === clientId ? confirmed : m)));
    } catch (err) {
      setMessages(prev => prev.map(m => (m.id === clientId ? { ...m, pending: false } : m)));
      setError(err instanceof Error ? err.message : 'Message failed to send.');
    }
  }, [draft]);

  const renderItem = useCallback(({ item }: { item: Message }) => {
    const mine = item.senderId === MY_ID;
    return (
      <View style={[styles.bubbleWrap, mine ? styles.mineWrap : styles.theirsWrap]}>
        <View style={[styles.bubble, mine ? styles.mine : styles.theirs]}>
          <Text style={styles.bubbleText}>{item.text}</Text>
          {item.pending && <Text style={styles.pending}>sending…</Text>}
        </View>
      </View>
    );
  }, []);

  return (
    <SafeAreaView style={styles.safe}>
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined} style={styles.flex} keyboardVerticalOffset={0}>
        {loading && <ActivityIndicator color="{colors.accent}" style={styles.center} />}
        {!loading && error && <Text style={styles.error}>{error}</Text>}
        {!loading && !error && (
          <FlatList
            ref={listRef}
            data={sorted}
            renderItem={renderItem}
            keyExtractor={m => m.id}
            contentContainerStyle={styles.list}
            onContentSizeChange={() => listRef.current?.scrollToEnd({ animated: true })}
          />
        )}
        <View style={styles.inputBar}>
          <TextInput
            value={draft}
            onChangeText={setDraft}
            placeholder="Message"
            placeholderTextColor="{colors.muted}"
            accessibilityLabel="Message"
            style={styles.input}
          />
          <TouchableOpacity style={styles.send} onPress={send} accessibilityRole="button" accessibilityLabel="Send message">
            <Text style={styles.sendText}>➤</Text>
          </TouchableOpacity>
        </View>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  flex: { flex: 1 },
  list: { padding: 16, gap: 10 },
  bubbleWrap: { alignItems: 'flex-start' },
  mineWrap: { alignItems: 'flex-end' },
  theirsWrap: { alignItems: 'flex-start' },
  bubble: { maxWidth: '78%', borderRadius: 14, paddingHorizontal: 12, paddingVertical: 8 },
  mine: { backgroundColor: colors.accent },
  theirs: { backgroundColor: colors.border },
  bubbleText: { color: colors.text },
  pending: { color: colors.bg, fontSize: 10, marginTop: 2, opacity: 0.7 },
  inputBar: { flexDirection: 'row', alignItems: 'center', gap: 8, padding: 12, borderTopWidth: 1, borderTopColor: colors.border },
  input: { flex: 1, backgroundColor: colors.surface, color: colors.text, borderRadius: 18, paddingHorizontal: 14, paddingVertical: 10 },
  send: { width: 40, height: 40, borderRadius: 20, backgroundColor: colors.accent, alignItems: 'center', justifyContent: 'center' },
  sendText: { color: colors.bg, fontWeight: '700' },
  center: { marginTop: 40 },
  error: { color: colors.danger, textAlign: 'center', marginTop: 24 },
});
